
(function(){
"use strict";

/* League data: js/data-league.js (regenerated by scripts/pull_sleeper.py) */
/* Art + story: js/data-content.js (edit content/story.json and re-run scripts/build_content.py) */

const T = {}; L.teams.forEach(t => { T[t.id] = t; });
const WEEKS = Object.keys(L.weeks).map(Number).sort((a,b) => a-b);
const LAST = L.lastScoredWeek;
const CROWN = '<svg class="crown" viewBox="0 0 24 16" aria-hidden="true"><path d="M1 3.5l5.2 4.6L12 1l5.8 7.1L23 3.5 21.4 14H2.6z"/></svg>';

const TITLES = {};
(L.seasons || []).forEach(s => { (TITLES[s.champ] = TITLES[s.champ] || []).push(s.year); });
function stars(id){
  const y = TITLES[id]; if (!y) return '';
  return '<span class="stars" role="img" aria-label="'+(y.length > 1 ? y.length+' titles: ' : 'Champion, ')+y.join(", ")+'">'+new Array(y.length+1).join("\u2605")+'</span>';
}
const esc = s => String(s).replace(/[&<>"']/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const f2 = n => n.toFixed(2);
const sum = a => a.reduce((x,y) => x+y, 0);
const ord = n => { const s = ["th","st","nd","rd"], v = n % 100; return n + (s[(v-20)%10] || s[v] || s[0]); };
const best = (a, fn) => a.reduce((x,y) => fn(y) > fn(x) ? y : x);

/* ----- Derived season ----- */
const GAMES = [];
WEEKS.forEach(w => L.weeks[w].forEach((g,i) => {
  const a = g[0], pa = g[1], b = g[2], pb = g[3], aw = pa >= pb;
  GAMES.push({week:w, n:i+1, win:aw?a:b, wp:aw?pa:pb, lose:aw?b:a, lp:aw?pb:pa, margin:Math.abs(pa-pb)});
}));
const gamesOf = w => GAMES.filter(g => g.week === w);
const LOG = {}; L.teams.forEach(t => { LOG[t.id] = []; });
GAMES.forEach(g => {
  LOG[g.win].push({week:g.week, res:"W", pts:g.wp, opp:g.lose, oppPts:g.lp, margin:g.margin});
  LOG[g.lose].push({week:g.week, res:"L", pts:g.lp, opp:g.win, oppPts:g.wp, margin:g.margin});
});
const LEAGUE_AVG = sum(GAMES.map(g => g.wp + g.lp)) / (GAMES.length * 2);

function line(id, w){
  const rows = LOG[id].filter(r => r.week <= w);
  const W = rows.filter(r => r.res === "W").length;
  const type = rows.length ? rows[rows.length-1].res : "";
  let streak = 0;
  for (let i = rows.length-1; i >= 0 && rows[i].res === type; i--) streak++;
  return {id, w:W, l:rows.length-W, pf:sum(rows.map(r => r.pts)), pa:sum(rows.map(r => r.oppPts)), streak, type, rows};
}
function standings(w){ return L.teams.map(t => line(t.id, w)).sort((a,b) => b.w-a.w || b.pf-a.pf); }
function allPlay(id, w){
  let W = 0, Lo = 0, exp = 0;
  LOG[id].filter(r => r.week <= w).forEach(me => {
    let wk = 0, n = 0;
    L.teams.forEach(t => {
      if (t.id === id) return;
      const o = LOG[t.id].find(r => r.week === me.week); if (!o) return;
      n++; if (me.pts > o.pts) wk++; else if (me.pts < o.pts) Lo++;
    });
    W += wk; exp += n ? wk/n : 0;
  });
  return {w:W, l:Lo, exp};
}
function pairs(){
  const p = {};
  GAMES.forEach(g => {
    const a = Math.min(g.win,g.lose), b = Math.max(g.win,g.lose), k = a+"-"+b;
    (p[k] = p[k] || {a, b, key:k, games:[]}).games.push(g);
  });
  return p;
}
const REMATCHES = Object.values(pairs()).filter(p => p.games.length > 1);

/* ----- Slots ----- */
function art(key, ratio, label, opt){
  opt = opt || {};
  const src = ART[key];
  if (src){
    return opt.video
      ? '<video class="art" style="aspect-ratio:'+ratio+'" src="'+esc(src)+'" controls playsinline preload="metadata"></video>'
      : '<img class="art" style="aspect-ratio:'+ratio+'" src="'+esc(src)+'" alt="'+esc(opt.alt || label)+'">';
  }
  const file = "art/" + key + (opt.video ? ".mp4" : ".jpg");
  return '<div class="slot-art'+(opt.small?" sm":"")+'" style="aspect-ratio:'+ratio+'" role="img" aria-label="'+esc(label)+', art not added yet">'
    + (opt.mono ? '<span class="slot-mono" aria-hidden="true">'+esc(opt.mono)+'</span>' : '')
    + '<span class="slot-k">'+esc(label)+'</span>'
    + (opt.small ? '' : '<span class="slot-f">'+esc(file)+'</span>')
    + '</div>';
}
function story(key, label, tag, cls){
  const t = STORY[key];
  if (t) return '<'+tag+' class="'+cls+'">'+esc(t)+'</'+tag+'>';
  return '<'+tag+' class="'+cls+' slot-story"><span>'+esc(label)+'</span></'+tag+'>';
}
function chronicle(key, label){
  const t = STORY[key];
  if (!t) return story(key, label, "p", "lede");
  return '<div class="chron">' + String(t).split(/\n\n+/).map(b => /^## /.test(b)
    ? '<h3 class="chron-h">'+esc(b.slice(3))+'</h3>'
    : '<p class="lede">'+esc(b)+'</p>').join("") + '</div>';
}
const TEAM_FIELDS = [
  ["avatar","Avatar","Who this manager is in the saga, and how they look."],
  ["origin","Origin","How they entered the story."],
  ["arc","Current arc","Where their season stands in the story right now."],
  ["nemesis","Nemesis","The rival the story keeps sending them back to."]
];
function slotStatus(){
  const a = [], s = [];
  WEEKS.forEach(w => {
    a.push("w"+w+"/cover","w"+w+"/film"); s.push("w"+w+"/headline","w"+w+"/intro","w"+w+"/story");
    L.weeks[w].forEach((g,i) => { a.push("w"+w+"/m"+(i+1)); s.push("w"+w+"/m"+(i+1)+"/title","w"+w+"/m"+(i+1)+"/recap"); });
  });
  L.teams.forEach(t => { a.push("team/"+t.id); TEAM_FIELDS.forEach(f => s.push("team/"+t.id+"/"+f[0])); });
  REMATCHES.forEach(p => s.push("rivalry/"+p.key+"/name"));
  return {art:[a.filter(k => ART[k]).length, a.length], story:[s.filter(k => STORY[k]).length, s.length]};
}

/* ----- Small pieces ----- */
function teamLink(id, cls){
  cls = cls || "tm";
  return '<a class="'+cls+'" href="#team-'+id+'">'+esc(T[id].name)+(cls === "tl" ? '' : stars(id))+'</a>';
}
function badges(t){ return t.commish ? '<span class="bdg plain">Commish</span>' : ''; }
function titleBadge(id){ const y = TITLES[id]; return y ? '<span class="bdg">'+CROWN+y.join(", ")+' champion</span>' : ''; }
function tile(label, value, detail){
  return '<div class="tile"><span class="tile-l">'+label+'</span><span class="tile-v">'+value+'</span><span class="tile-d">'+detail+'</span></div>';
}
function formDots(rows){
  return '<span class="form" role="img" aria-label="Results by week: '+rows.map(r => r.res).join(" ")+'">'
    + rows.map(r => '<i class="'+(r.res==="W"?"w":"")+'"></i>').join("") + '</span>';
}
function chips(g){
  const gs = gamesOf(g.week), upTo = GAMES.filter(x => x.week <= g.week), out = [];
  const hi = Math.max.apply(null, gs.map(x => x.wp)), lo = Math.min.apply(null, gs.map(x => x.lp));
  const sHi = Math.max.apply(null, upTo.map(x => x.wp)), sLo = Math.min.apply(null, upTo.map(x => x.lp));
  if (g.wp === sHi && g.week > 1) out.push(["up","Season high"]); else if (g.wp === hi) out.push(["up","Week high"]);
  if (g.lp === sLo && g.week > 1) out.push(["down","Season low"]); else if (g.lp === lo) out.push(["down","Week low"]);
  if (g.margin < 5) out.push(["","Nail-biter"]); else if (g.margin >= 40) out.push(["","Blowout"]);
  if (g.week >= 4 && line(g.lose, g.week-1).w - line(g.win, g.week-1).w >= 2) out.push(["up","Upset"]);
  const ws = line(g.win, g.week).streak, ls = line(g.lose, g.week).streak;
  if (ws >= 3) out.push(["up","Won "+ws+" straight"]);
  if (ls >= 3) out.push(["down","Lost "+ls+" straight"]);
  return out.map(c => '<span class="chip '+c[0]+'">'+c[1]+'</span>').join("");
}
function gameCard(g){
  const k = "w"+g.week+"/m"+g.n, wl = line(g.win, g.week), ll = line(g.lose, g.week);
  return '<article class="game">'
    + art(k, "16/9", "Matchup "+g.n+" art")
    + '<div class="game-body">'
    + story(k+"/title", "Matchup title", "h3", "game-title")
    + '<div class="lines">'
    + '<div class="line win"><span class="side">'+teamLink(g.win)+'<span class="rec">'+wl.w+'-'+wl.l+'</span><span class="sr"> won</span></span><span class="pts">'+f2(g.wp)+'</span></div>'
    + '<div class="line lose"><span class="side">'+teamLink(g.lose)+'<span class="rec">'+ll.w+'-'+ll.l+'</span></span><span class="pts">'+f2(g.lp)+'</span></div>'
    + '</div>'
    + '<div class="game-foot"><span class="margin">By '+f2(g.margin)+'</span>'+chips(g)+'</div>'
    + story(k+"/recap", "Recap. Two or three sentences from the lore bible.", "p", "recap")
    + '</div></article>';
}

/* ----- Views ----- */
function viewSlate(){
  const s = L.slate, rank = {};
  standings(LAST).forEach((r,i) => { rank[r.id] = i+1; });
  const rows = s.games.map(p => {
    let a = p[0], b = p[1];
    if (rank[b] < rank[a]) { const x = a; a = b; b = x; }
    const la = line(a, LAST), lb = line(b, LAST);
    const met = GAMES.filter(g => (g.win===a && g.lose===b) || (g.win===b && g.lose===a));
    return {a, b, la, lb, met, heat:la.w+lb.w, pf:la.pf+lb.pf};
  }).sort((x,y) => y.heat-x.heat || y.pf-x.pf);
  return '<section class="sec"><h2 class="sec-h">Up next: Week '+s.week+'</h2><div class="slate">'
    + rows.map((r,i) => '<div class="slate-row"><div class="slate-teams">'
        + teamLink(r.a)+'<span class="rec">'+r.la.w+'-'+r.la.l+'</span><span class="vs">vs</span>'
        + teamLink(r.b)+'<span class="rec">'+r.lb.w+'-'+r.lb.l+'</span>'
        + (i===0 ? '<span class="chip up">Game of the week</span>' : '')
        + '</div><div class="slate-note">'
        + (r.met.length ? r.met.map(g => 'Week '+g.week+': '+esc(T[g.win].name)+' won '+f2(g.wp)+' to '+f2(g.lp)).join(" · ") : 'First meeting this season')
        + '</div></div>').join("")
    + '</div><p class="note">Week '+s.week+' is in progress. Its issue publishes once the scores are final.</p></section>';
}
function viewIssue(w){
  const gs = gamesOf(w), latest = w === LAST;
  const hi = best(gs, g => g.wp), close = best(gs, g => -g.margin), blow = best(gs, g => g.margin), tough = best(gs, g => g.lp);
  const prev = WEEKS.indexOf(w-1) > -1, next = WEEKS.indexOf(w+1) > -1;
  return '<section class="hero">'
    + '<div class="hero-head"><p class="eyebrow">Issue '+w+(latest?' · Latest':'')+'</p>'
    + story("w"+w+"/headline", "Week "+w+" headline", "h1", "headline")
    + '<p class="dateline">'+esc(L.name)+' <span aria-hidden="true">&mdash;</span> Week '+w+'</p></div>'
    + '<div class="hero-art">'+art("w"+w+"/cover", "4/5", "Week "+w+" cover")+'</div>'
    + '<div class="hero-lede">'+story("w"+w+"/intro", "Opening chapter. Three or four sentences on where the saga stands this week.", "p", "lede")+'</div>'
    + '</section>'
    + '<section class="sec"><h2 class="sec-h">Week '+w+' in numbers</h2><div class="tiles">'
    + tile("High score", f2(hi.wp), teamLink(hi.win,"tl"))
    + tile("Closest game", f2(close.margin), teamLink(close.win,"tl")+' over '+teamLink(close.lose,"tl"))
    + tile("Biggest margin", f2(blow.margin), teamLink(blow.win,"tl")+' over '+teamLink(blow.lose,"tl"))
    + tile("Most points in a loss", f2(tough.lp), teamLink(tough.lose,"tl"))
    + '</div></section>'
    + '<section class="sec"><h2 class="sec-h">Matchups</h2><div class="games">'+gs.map(gameCard).join("")+'</div></section>'
    + '<section class="sec"><h2 class="sec-h">Film of the week</h2><div class="film">'+art("w"+w+"/film", "16/9", "Film of the week", {video:true})+'</div></section>'
    + '<section class="sec"><h2 class="sec-h">The Story</h2>'+chronicle("w"+w+"/story", "The weekly chronicle. A longer recap of this week\'s chapter in the saga.")+'</section>'
    + (latest && L.slate ? viewSlate() : '')
    + '<nav class="pager" aria-label="Other issues">'
    + (prev ? '<a class="btn" href="#week-'+(w-1)+'"><span aria-hidden="true">&larr;</span> Week '+(w-1)+'</a>' : '<span></span>')
    + (next ? '<a class="btn" href="#week-'+(w+1)+'">Week '+(w+1)+' <span aria-hidden="true">&rarr;</span></a>' : '<a class="btn" href="#archive">All issues</a>')
    + '</nav>';
}
function viewArchive(){
  return '<header class="page-h"><h1 class="page-t">Archive</h1><p class="page-s">Every issue this season, newest first.</p></header><div class="wall">'
    + WEEKS.slice().reverse().map(w => {
        const hi = best(gamesOf(w), g => g.wp);
        return '<a class="poster" href="#week-'+w+'">'+art("w"+w+"/cover", "4/5", "Week "+w+" cover", {small:true})
          + '<span class="poster-wk">Week '+w+(w===LAST?' · Latest':'')+'</span>'
          + story("w"+w+"/headline", "Headline", "span", "poster-t")
          + '<span class="poster-f">High score: '+esc(T[hi.win].name)+', '+f2(hi.wp)+'</span></a>';
      }).join("")
    + '</div>'
    + '<section class="sec"><h2 class="sec-h">Where it started</h2><figure class="origin">'
    + '<img src="art/origin.jpg" width="960" height="960" loading="lazy" alt="The original league art: an armored knight raising a football trophy under stadium lights, titled The Greatest Dynasty Ever">'
    + '<figcaption>The league\'s first picture, from Season 1 in 2025. <a class="inl" href="#trophy">See how that season ended</a></figcaption></figure></section>';
}
function viewStandings(){
  const st = standings(LAST);
  return '<header class="page-h"><h1 class="page-t">Standings</h1><p class="page-s">Through Week '+LAST+'. Ties in record break on points for.</p></header>'
    + '<div class="tbl-wrap"><table><thead><tr><th class="l">#</th><th class="l">Team</th><th>W-L</th><th>PF</th><th class="hide-sm">PA</th><th class="hide-sm">All-play</th><th>Strk</th></tr></thead><tbody>'
    + st.map((r,i) => {
        const t = T[r.id], ap = allPlay(r.id, LAST);
        return '<tr><td class="l rank">'+(i+1)+'</td><td class="l team">'+teamLink(r.id,"tm2")+badges(t)+'<span class="handle">@'+esc(t.handle)+'</span>'+formDots(r.rows)+'</td>'
          + '<td>'+r.w+'-'+r.l+'</td><td>'+f2(r.pf)+'</td><td class="hide-sm">'+f2(r.pa)+'</td><td class="hide-sm">'+ap.w+'-'+ap.l+'</td>'
          + '<td class="'+(r.type==="W"?"up":"down")+'">'+r.type+r.streak+'</td></tr>'
          + (i+1 === L.playoffTeams ? '<tr class="cut"><td colspan="7">Playoff line · Top '+L.playoffTeams+' advance · Playoffs start Week '+L.playoffWeekStart+'</td></tr>' : '');
      }).join("")
    + '</tbody></table></div>'
    + '<p class="note">Squares under each team show every week in order: filled for a win, hollow for a loss. PF is points for, PA is points against. All-play is the record a team would have if it played every other team every week.</p>';
}
function fighterStats(id, all){
  const me = all.find(x => x.id === id);
  const norm = k => { const v = all.map(x => x[k]), lo = Math.min.apply(null, v), hi = Math.max.apply(null, v); return hi === lo ? 50 : 12 + 88*(me[k]-lo)/(hi-lo); };
  return [
    ["Scoring", norm("ppg"), f2(me.ppg)+' avg'],
    ["Peak", norm("peak"), f2(me.peak)],
    ["Form", 12 + 88*me.form/5, me.form+'-'+(5-me.form)+' last 5'],
    ["Luck", norm("luck"), (me.luck >= 0 ? '+' : '&minus;')+Math.abs(me.luck).toFixed(1)+' wins']
  ];
}
function viewManagers(){
  const st = standings(LAST);
  const all = st.map(r => {
    const ap = allPlay(r.id, LAST), rows = r.rows;
    return {id:r.id, ppg:r.pf/rows.length, peak:Math.max.apply(null, rows.map(x => x.pts)),
            form:rows.slice(-5).filter(x => x.res === "W").length, luck:r.w - ap.exp};
  });
  return '<header class="page-h"><h1 class="page-t">Managers</h1><p class="page-s">All ten, in standings order. The bars compare each one with the rest of the league this season. Open a card for the full profile.</p></header>'
    + '<div class="roster">'
    + st.map((r,i) => {
        const t = T[r.id];
        return '<a class="fcard" href="#team-'+t.id+'"><div class="fcard-art">'
          + art("team/"+t.id, "3/4", "Portrait", {small:true, mono:t.abbr, alt:"Portrait of "+t.name})
          + '<div class="fcard-name"><span class="fcard-r">'+ord(i+1)+' · '+r.w+'-'+r.l+'</span><span class="fcard-t">'+esc(t.name)+stars(t.id)+'</span><span class="fcard-h">@'+esc(t.handle)+'</span></div></div>'
          + '<div class="fbars">'+fighterStats(t.id, all).map(s => '<div class="bar"><span class="bar-l">'+s[0]+'</span><span class="bar-v">'+s[2]+'</span><span class="bar-t"><i style="width:'+s[1].toFixed(0)+'%"></i></span></div>').join("")+'</div>'
          + '<span class="fcard-go">Full profile <span aria-hidden="true">&rarr;</span></span></a>';
      }).join("")
    + '</div>';
}
function chart(rows){
  const W = 340, H = 172, pl = 26, pr = 6, pt = 14, pb = 22, max = 200;
  const iw = W-pl-pr, ih = H-pt-pb, bw = iw/rows.length, y = v => pt + ih - (v/max)*ih;
  let s = '<svg class="chart" viewBox="0 0 '+W+' '+H+'" role="img" aria-label="Points scored each week, with wins and losses">';
  [0,50,100,150,200].forEach(v => {
    s += '<line class="grid" x1="'+pl+'" x2="'+(W-pr)+'" y1="'+y(v)+'" y2="'+y(v)+'"/><text class="ax" x="'+(pl-5)+'" y="'+(y(v)+3)+'" text-anchor="end">'+v+'</text>';
  });
  rows.forEach((r,i) => {
    const x = pl + i*bw + bw*0.16, w = bw*0.68, yy = y(r.pts), cx = (x+w/2).toFixed(1);
    s += '<rect class="'+(r.res==="W"?"bw":"bl")+'" x="'+x.toFixed(1)+'" y="'+yy.toFixed(1)+'" width="'+w.toFixed(1)+'" height="'+(pt+ih-yy).toFixed(1)+'"/>'
       + '<text class="val" x="'+cx+'" y="'+(yy-3).toFixed(1)+'" text-anchor="middle">'+Math.round(r.pts)+'</text>'
       + '<text class="ax" x="'+cx+'" y="'+(H-7)+'" text-anchor="middle">'+r.week+'</text>';
  });
  s += '<line class="avg" x1="'+pl+'" x2="'+(W-pr)+'" y1="'+y(LEAGUE_AVG).toFixed(1)+'" y2="'+y(LEAGUE_AVG).toFixed(1)+'"/></svg>';
  return s;
}
function viewTeam(id){
  const t = T[id], st = standings(LAST), rank = st.findIndex(r => r.id === id) + 1, r = st[rank-1], ap = allPlay(id, LAST);
  const rows = r.rows, hi = best(rows, x => x.pts), lo = best(rows, x => -x.pts);
  const wins = rows.filter(x => x.res === "W"), losses = rows.filter(x => x.res === "L");
  const bw = wins.length ? best(wins, x => x.margin) : null, wl = losses.length ? best(losses, x => x.margin) : null;
  const luck = r.w - ap.exp, b = titleBadge(id) + badges(t);
  const last = (L.seasons || []).slice().sort((x,y) => y.year - x.year)[0];
  let lastLine = '';
  if (last){
    const o = last.teams.find(x => x.id === id), place = last.finish.indexOf(id) + 1;
    if (o) lastLine = '<p class="who-next">'+last.year+': '+o.w+'-'+o.l+', '+(place === 1 ? 'champion' : 'finished '+ord(place))+(o.name !== t.name ? ' as '+esc(o.name) : '')+'</p>';
  }
  const nx = L.slate ? L.slate.games.find(p => p[0] === id || p[1] === id) : null;
  const nxOpp = nx ? (nx[0] === id ? nx[1] : nx[0]) : null;
  const vs = x => 'Week '+x.week+' vs '+teamLink(x.opp,"tl");
  return '<a class="back" href="#managers"><span aria-hidden="true">&larr;</span> All managers</a>'
    + '<section class="who"><div>'+art("team/"+id, "3/4", "Portrait", {small:true, mono:t.abbr, alt:"Portrait of "+t.name})+'</div><div>'
    + '<h1>'+esc(t.name)+stars(id)+'</h1><p class="who-h">@'+esc(t.handle)+' · '+ord(rank)+' of '+L.teams.length+'</p>'
    + (b ? '<div class="who-b">'+b+'</div>' : '')
    + (nxOpp ? '<p class="who-next">Next: Week '+L.slate.week+' vs '+teamLink(nxOpp,"tl")+'</p>' : '')
    + lastLine
    + '</div></section>'
    + '<section class="sec"><h2 class="sec-h">Character sheet</h2><dl class="sheet">'
    + TEAM_FIELDS.map(f => '<div><dt>'+f[1]+'</dt>'+story("team/"+id+"/"+f[0], f[2], "dd", "")+'</div>').join("")
    + '</dl></section>'
    + '<section class="sec"><h2 class="sec-h">Season in numbers</h2><div class="tiles">'
    + tile("Record", r.w+'-'+r.l, (r.type==="W"?"Won ":"Lost ")+r.streak+' straight')
    + tile("Points for", f2(r.pf), f2(r.pf/rows.length)+' a week')
    + tile("Points against", f2(r.pa), f2(r.pa/rows.length)+' a week')
    + tile("All-play", ap.w+'-'+ap.l, 'Luck '+(luck >= 0 ? '+' : '&minus;')+Math.abs(luck).toFixed(1)+' wins')
    + tile("High week", f2(hi.pts), vs(hi))
    + tile("Low week", f2(lo.pts), vs(lo))
    + tile("Biggest win", bw ? f2(bw.margin) : '&ndash;', bw ? vs(bw) : 'No wins yet')
    + tile("Worst loss", wl ? f2(wl.margin) : '&ndash;', wl ? vs(wl) : 'No losses yet')
    + '</div><p class="note">All-play is the record against every other team every week. Luck is real wins minus the wins that record predicts.</p></section>'
    + '<section class="sec"><h2 class="sec-h">Week by week</h2><div class="chart-box">'+chart(rows)
    + '<div class="keyrow"><span><i class="sw w"></i>Win</span><span><i class="sw l"></i>Loss</span><span><i class="sw a"></i>League average, '+f2(LEAGUE_AVG)+'</span></div></div>'
    + '<div class="tbl-wrap" style="margin-top:14px"><table><thead><tr><th class="l">Wk</th><th class="l">Opponent</th><th>Result</th><th>Score</th></tr></thead><tbody>'
    + rows.map(x => '<tr><td class="l"><a class="wk-link" href="#week-'+x.week+'">'+x.week+'</a></td><td class="l team">'+teamLink(x.opp,"tm2")+'</td>'
        + '<td class="'+(x.res==="W"?"up":"down")+'">'+x.res+'</td><td>'+f2(x.pts)+' &ndash; '+f2(x.oppPts)+'</td></tr>').join("")
    + '</tbody></table></div></section>';
}
function viewRivalries(){
  const order = standings(LAST).map(r => r.id), P = pairs();
  const re = REMATCHES.map(p => {
    const aw = p.games.filter(g => g.win === p.a).length, bw = p.games.length - aw;
    const ap = sum(p.games.map(g => g.win === p.a ? g.wp : g.lp)), bp = sum(p.games.map(g => g.win === p.b ? g.wp : g.lp));
    return {p, aw, bw, ap, bp, gap:Math.abs(ap-bp)};
  }).sort((x,y) => x.gap - y.gap);
  const cards = re.map(x => {
    const p = x.p, lead = x.aw === x.bw ? null : (x.aw > x.bw ? p.a : p.b);
    const series = lead ? 'Series: '+esc(T[lead].name)+' '+Math.max(x.aw,x.bw)+'-'+Math.min(x.aw,x.bw) : 'Series tied '+x.aw+'-'+x.bw;
    return '<article class="rv">'+story("rivalry/"+p.key+"/name", "Rivalry name", "h3", "rv-name")
      + '<div class="rv-pair">'+teamLink(p.a)+'<span class="vs">vs</span>'+teamLink(p.b)+'</div>'
      + '<div><span class="chip'+(lead?' up':'')+'">'+series+'</span></div>'
      + '<ul class="rv-list">'+p.games.map(g => '<li><b>Week '+g.week+'</b>'+esc(T[g.win].name)+' won '+f2(g.wp)+' to '+f2(g.lp)+'</li>').join("")
      + '<li><b>Total</b>'+esc(T[p.a].abbr)+' '+f2(x.ap)+', '+esc(T[p.b].abbr)+' '+f2(x.bp)+'</li></ul></article>';
  }).join("");
  const cell = (a,b) => {
    if (a === b) return '<td class="self"></td>';
    const k = Math.min(a,b)+"-"+Math.max(a,b), g = P[k] ? P[k].games : [];
    if (!g.length) return '<td class="none">&middot;</td>';
    const w = g.filter(x => x.win === a).length, l = g.length - w;
    return '<td class="'+(w>l?"up":w<l?"down":"")+'">'+w+'-'+l+'</td>';
  };
  return '<header class="page-h"><h1 class="page-t">Rivalries</h1><p class="page-s">Pairs that have already met twice, closest on total points first, then every head-to-head this season.</p></header>'
    + '<section><h2 class="sec-h">Rematches</h2><div class="riv">'+(cards || '<p class="note">No pair has met twice yet.</p>')+'</div></section>'
    + '<section class="sec"><h2 class="sec-h">Head to head</h2><div class="tbl-wrap"><table class="h2h"><thead><tr><th class="l"><span class="sr">Team</span></th>'
    + order.map(b => '<th scope="col">'+esc(T[b].abbr)+'</th>').join("")+'</tr></thead><tbody>'
    + order.map(a => '<tr><th class="l" scope="row">'+esc(T[a].abbr)+'</th>'+order.map(b => cell(a,b)).join("")+'</tr>').join("")
    + '</tbody></table></div><p class="note">Read across: the row team\'s record against the column team. A dot means they have not played yet.</p>'
    + '<ul class="abbr-key">'+order.map(a => '<li><b>'+esc(T[a].abbr)+'</b>'+esc(T[a].name)+'</li>').join("")+'</ul></section>';
}

function seasonBlock(s){
  const by = {}; s.teams.forEach(o => { by[o.id] = o; });
  const nm = id => esc(by[id].name);
  const old = (id, cls) => '<a class="'+cls+'" href="#team-'+id+'">'+nm(id)+'</a>';
  const seeds = s.teams.slice().sort((a,b) => b.w-a.w || b.pf-a.pf).map(o => o.id);
  const fin = s.playoffs.find(p => p.final), g = fin.games[0];
  return '<section class="sec"><h2 class="sec-h">The '+s.year+' final</h2><div class="final">'
    + '<div class="line win"><span class="side">'+old(g[0],"tm")+'<span class="rec">'+by[g[0]].w+'-'+by[g[0]].l+'</span><span class="sr"> won</span></span><span class="pts">'+f2(g[1])+'</span></div>'
    + '<div class="line lose"><span class="side">'+old(g[2],"tm")+'<span class="rec">'+by[g[2]].w+'-'+by[g[2]].l+'</span></span><span class="pts">'+f2(g[3])+'</span></div>'
    + '<div class="game-foot"><span class="margin">Week '+fin.week+' · By '+f2(g[1]-g[3])+'</span><span class="chip up">'+s.year+' champion: '+nm(g[0])+'</span></div></div></section>'
    + '<section class="sec"><h2 class="sec-h">'+s.year+' playoffs</h2><div class="riv">'
    + s.playoffs.map(p => '<article class="rv"><h3 class="round-h">'+esc(p.round)+' · Week '+p.week+'</h3><ul class="rv-list">'
        + p.games.map(x => '<li>'+nm(x[0])+' <span class="sc">'+f2(x[1])+'</span> over '+nm(x[2])+' <span class="sc">'+f2(x[3])+'</span></li>').join("")
        + '</ul></article>').join("")
    + '</div></section>'
    + '<section class="sec"><h2 class="sec-h">'+s.year+' final standings</h2><div class="tbl-wrap"><table><thead><tr><th class="l">#</th><th class="l">Team</th><th class="hide-sm">Seed</th><th>'+s.year+'</th><th class="hide-sm">PF</th><th>'+L.season+'</th></tr></thead><tbody>'
    + s.finish.map((id,i) => {
        const o = by[id], cur = line(id, LAST);
        return '<tr><td class="l rank">'+(i+1)+'</td><td class="l team"><a class="tm2" href="#team-'+id+'">'+nm(id)+(id === s.champ ? '<span class="stars" role="img" aria-label="Champion">\u2605</span>' : '')+'</a>'
          + (o.name !== T[id].name ? '<span class="handle">now '+esc(T[id].name)+'</span>' : '')+'</td>'
          + '<td class="hide-sm">'+(seeds.indexOf(id)+1)+'</td><td>'+o.w+'-'+o.l+'</td><td class="hide-sm">'+f2(o.pf)+'</td><td>'+cur.w+'-'+cur.l+'</td></tr>'
          + (i+1 === s.playoffTeams ? '<tr class="cut"><td colspan="6">Playoff line</td></tr>' : '');
      }).join("")
    + '</tbody></table></div><p class="note">Places 1 to '+s.playoffTeams+' come from the playoffs. The rest follow regular-season record. The '+L.season+' column is each franchise this season, through Week '+LAST+'.</p></section>';
}
function viewTrophy(){
  const seasons = (L.seasons || []).slice().sort((a,b) => a.year - b.year), st = standings(LAST);
  return '<header class="page-h"><h1 class="page-t">Trophy Room</h1><p class="page-s">One trophy. A new plate every season.</p></header>'
    + '<section class="troph"><img class="troph-img" src="art/trophy.jpg" width="700" height="1399" alt="The league trophy: a black football on a fluted column. Its silver plate reads Champion, The Greatest Dynasty Ever.">'
    + '<div class="plates">'
    + seasons.map(s => '<div class="plate"><span class="plate-y">'+esc(s.plate[0])+'</span>'+s.plate.slice(1).map(x => '<span class="plate-n">'+esc(x)+'</span>').join("")+'</div>').join("")
    + '<div class="plate blank"><span class="plate-y">'+L.season+'</span><span class="plate-n">To be engraved</span></div>'
    + '<p class="note">Top '+L.playoffTeams+' make the playoffs. They start Week '+L.playoffWeekStart+'.</p>'
    + '</div></section>'
    + '<section class="sec"><h2 class="sec-h">Race for the '+L.season+' plate</h2><ol class="race">'
    + st.slice(0, L.playoffTeams).map((r,i) => '<li><span class="race-n">'+(i+1)+'</span><span class="race-t">'+teamLink(r.id)+'</span><span class="rec">'+r.w+'-'+r.l+'</span></li>').join("")
    + '</ol><p class="note">Inside the playoff line through Week '+LAST+'. <a class="inl" href="#standings">Full standings</a></p></section>'
    + seasons.slice().reverse().map(seasonBlock).join("");
}

/* ----- Chrome ----- */
document.getElementById("mast-sub").textContent = "Season " + L.season + " · Through Week " + LAST;
(function(){
  const s = slotStatus();
  document.getElementById("foot").innerHTML =
    '<ul class="legend">'
    + '<li><span class="k-live" aria-hidden="true">'+LAST+'</span><span>Scores, records and standings come from Sleeper, through Week '+LAST+'. Pulled '+esc(L.pulled)+'. Last season comes from the 2025 Sleeper league.</span></li>'
    + '<li><span class="k-art" aria-hidden="true"></span><span>Hatched frames are waiting on art. Each one names the file it expects. Art added: '+s.art[0]+' of '+s.art[1]+'.</span></li>'
    + '<li><span class="k-story" aria-hidden="true">&para;</span><span>Dashed lines are story still to be written or confirmed. Story added: '+s.story[0]+' of '+s.story[1]+'.</span></li>'
    + '</ul><p class="foot-meta">'+esc(L.name)+' · Sleeper league '+esc(L.id)+'</p>';
})();

/* ----- Router ----- */
const app = document.getElementById("app"), mast = document.querySelector(".mast");
const PROTO = '<p class="proto"><b>In progress</b>Scores are real, from Sleeper. Story and matchup art run through Week 11. Covers for Weeks 1&ndash;5 are still being added.</p>';
let current = null;
function render(h, scroll){
  h = String(h || "").replace(/^#/, "") || "issue";
  let m, html, tab;
  if ((m = h.match(/^week-(\d+)$/)) && L.weeks[m[1]]) { html = viewIssue(+m[1]); tab = +m[1] === LAST ? "issue" : "archive"; }
  else if ((m = h.match(/^team-(\d+)$/)) && T[m[1]]) { html = viewTeam(+m[1]); tab = "managers"; }
  else if (h === "archive") { html = viewArchive(); tab = "archive"; }
  else if (h === "standings") { html = viewStandings(); tab = "standings"; }
  else if (h === "managers") { html = viewManagers(); tab = "managers"; }
  else if (h === "rivalries") { html = viewRivalries(); tab = "rivalries"; }
  else if (h === "trophy") { html = viewTrophy(); tab = "trophy"; }
  else { h = "issue"; html = viewIssue(LAST); tab = "issue"; }
  app.innerHTML = PROTO + html;
  document.querySelectorAll(".nav a").forEach(a => {
    if (a.dataset.tab === tab) a.setAttribute("aria-current", "page"); else a.removeAttribute("aria-current");
  });
  current = h;
  if (scroll) window.scrollTo(0, Math.min(window.scrollY, mast.offsetHeight));
}
document.addEventListener("click", e => {
  const a = e.target.closest ? e.target.closest('a[href^="#"]') : null;
  if (!a || e.metaKey || e.ctrlKey || e.shiftKey || e.button) return;
  e.preventDefault();
  const h = a.getAttribute("href");
  try { if (location.hash !== h) location.hash = h; } catch (_) {}
  if (current !== h.slice(1)) render(h, true);
});
window.addEventListener("hashchange", () => {
  const h = location.hash.replace(/^#/, "") || "issue";
  if (h !== current) render(h, true);
});
render(location.hash, false);
})();
